import WeightInfo from "../molecules/weightInfo";
import {WeightInfoProps} from "../molecules/weightInfo";
import { useLocalStorage } from "@uidotdev/usehooks";
import WeightCard from "../organisms/weightCard";





const PageWeightCalulator = () => {

    const [length, setLength] = useLocalStorage("length", 10); 
    const [width, setwidth] = useLocalStorage("width", 10); 
    const [grammage, setGrammage] = useLocalStorage("grammage", 10); 
    const [numberOfSheets, setNumberOfSheets] = useLocalStorage("numberOfSheets", 10); 
    const [format, setFormat] = useLocalStorage("format", "A2"); 



    return (


        <>

            <h1>Page Calculator</h1>

            <WeightCard length={length} width={width} grammage={grammage} numberOfSheets={numberOfSheets} setNumberOfSheets={setNumberOfSheets} />

        </>
    )
}


export default PageWeightCalulator
